{
  "findings": [
    {
      "check_id": "CKV_GCP_1",
      "title": "Unrestricted ingress from 0.0.0.0/0",
      "resource": "google_compute_firewall.allow_http_https",
      "severity": "HIGH",
      "explanation": "The firewall rule allows unrestricted ingress traffic from any IP address (0.0.0.0/0) to ports 80, 443, and 8080. This exposes the application to potential attacks from the internet. Restricting the source IP range to known trusted IPs or ranges reduces the attack surface."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http_https\" {\n  name    = \"digital-asset-trading-platform-firewall-web\"\n  network = google_compute_network.digital_asset_trading_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"80\", \"443\", \"8080\"]\n  }\n  source_ranges = [\"192.168.1.0/24\"] # Replace with your trusted IP range\n  target_tags   = [\"web-server\"]\n}",
  "fix_summary": "Restricted the source_ranges from 0.0.0.0/0 to a placeholder trusted IP range (192.168.1.0/24). This reduces the risk of unauthorized access from the internet."
}
